      tlm_version: 1, temperature_C: tlm.temp_c, humidity_pct: tlm.rh_pct,
      ir: tlm.ir, gas_raw: tlm.gas_raw, us1_cm: tlm.us1_cm, us2_cm: tlm.us2_cm,
      range_min_m: us.length ? Math.min(...us) / 100 : null,
